import json,numpy as np
D=np.load('/app/output/observations/001_obs/egocentric_mirrored_camera_depth.npy')
C=json.load(open('/app/output/observations/001_obs/meta.json'))['cameras']['egocentric_mirrored_camera']; K=np.array(C['intrinsic_cv']); E=np.array(C['extrinsic_cv']); R=E[:,:3]; t=E[:,3]
def wp(u,v,z): return np.linalg.solve(R,np.array([(u-K[0,2])/K[0,0]*z,(v-K[1,2])/K[1,1]*z,z])-t)
def rayplane(u,v,Z=0):
 p0=np.linalg.solve(R,np.array([0.,0.,0.])-t)
 d=np.linalg.solve(R,np.array([(u-K[0,2])/K[0,0],(v-K[1,2])/K[1,1],1.]))
 return p0+d*((Z-p0[2])/d[2])
points={'lime_left':(338,220),'orange_a':(412,190),'orange_b':(414,235),'pomegranate':(465,275),'lime_right':(496,170),'lemon_right':(604,190),'lemon_center':(477,220),'small_pumpkin':(580,235),'large_pumpkin':(610,280),'onion':(585,365),'bin_center':(200,185)}
for k,(u,v) in points.items():
 z=float(D[v,u]); p=wp(u,v,z)
 print(k,'pix',u,v,'d',round(z,3),'world_surface',np.round(p,3),'world_floor',np.round(rayplane(u,v),3))
